-- Live attention is derived from native records; reminders only retain identity.
CREATE TABLE penny_triage_settings (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1), inbox_days INTEGER NOT NULL DEFAULT 7 CHECK(inbox_days BETWEEN 1 AND 3650),
 comment_days INTEGER NOT NULL DEFAULT 7 CHECK(comment_days BETWEEN 1 AND 3650), response_days INTEGER NOT NULL DEFAULT 7 CHECK(response_days BETWEEN 1 AND 3650),
 under_review_days INTEGER NOT NULL DEFAULT 28 CHECK(under_review_days BETWEEN 1 AND 3650), planned_days INTEGER NOT NULL DEFAULT 28 CHECK(planned_days BETWEEN 1 AND 3650),
 in_progress_days INTEGER NOT NULL DEFAULT 28 CHECK(in_progress_days BETWEEN 1 AND 3650), updated_at TEXT NOT NULL
);
INSERT INTO penny_triage_settings(singleton,updated_at) VALUES(1,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
CREATE TABLE penny_triage_status_clock (
 request_id TEXT PRIMARY KEY REFERENCES requests(id) ON DELETE CASCADE,status TEXT NOT NULL,since_at TEXT NOT NULL
);
INSERT INTO penny_triage_status_clock(request_id,status,since_at) SELECT r.id,p.status,COALESCE(p.changed_at,r.published_at,r.created_at) FROM requests r JOIN penny_request_status p ON p.request_id=r.id;
CREATE TRIGGER triage_clock_request_insert AFTER INSERT ON requests WHEN (SELECT phase FROM data_state WHERE singleton=1)='idle' BEGIN INSERT INTO penny_triage_status_clock(request_id,status,since_at) SELECT r.id,p.status,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM requests r JOIN penny_request_status p ON p.request_id=r.id WHERE r.id=NEW.id ON CONFLICT(request_id) DO UPDATE SET status=excluded.status,since_at=excluded.since_at WHERE penny_triage_status_clock.status!=excluded.status; END;
CREATE TRIGGER triage_clock_request_update AFTER UPDATE ON requests WHEN (SELECT phase FROM data_state WHERE singleton=1)='idle' BEGIN INSERT INTO penny_triage_status_clock(request_id,status,since_at) SELECT r.id,p.status,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM requests r JOIN penny_request_status p ON p.request_id=r.id WHERE r.id=NEW.id ON CONFLICT(request_id) DO UPDATE SET status=excluded.status,since_at=excluded.since_at WHERE penny_triage_status_clock.status!=excluded.status; END;
CREATE TRIGGER triage_clock_mapping_update AFTER UPDATE ON roadmap_request_mappings WHEN (SELECT phase FROM data_state WHERE singleton=1)='idle' BEGIN INSERT INTO penny_triage_status_clock(request_id,status,since_at) SELECT r.id,p.status,COALESCE(strftime('%Y-%m-%dT%H:%M:%fZ','now'),p.changed_at,r.published_at,r.created_at) FROM requests r JOIN penny_request_status p ON p.request_id=r.id WHERE r.id=NEW.request_id ON CONFLICT(request_id) DO UPDATE SET status=excluded.status,since_at=excluded.since_at WHERE penny_triage_status_clock.status!=excluded.status; END;
CREATE TRIGGER triage_clock_mapping_delete AFTER DELETE ON roadmap_request_mappings WHEN (SELECT phase FROM data_state WHERE singleton=1)='idle' BEGIN INSERT INTO penny_triage_status_clock(request_id,status,since_at) SELECT r.id,p.status,COALESCE(strftime('%Y-%m-%dT%H:%M:%fZ','now'),p.changed_at,r.published_at,r.created_at) FROM requests r JOIN penny_request_status p ON p.request_id=r.id WHERE r.id=OLD.request_id ON CONFLICT(request_id) DO UPDATE SET status=excluded.status,since_at=excluded.since_at WHERE penny_triage_status_clock.status!=excluded.status; END;
CREATE TRIGGER triage_clock_publication_update AFTER UPDATE ON roadmap_publications WHEN (SELECT phase FROM data_state WHERE singleton=1)='idle' BEGIN INSERT INTO penny_triage_status_clock(request_id,status,since_at) SELECT r.id,p.status,COALESCE(strftime('%Y-%m-%dT%H:%M:%fZ','now'),p.changed_at,r.published_at,r.created_at) FROM requests r JOIN penny_request_status p ON p.request_id=r.id WHERE r.id IN (SELECT request_id FROM roadmap_request_mappings WHERE roadmap_item_id=NEW.roadmap_item_id) ON CONFLICT(request_id) DO UPDATE SET status=excluded.status,since_at=excluded.since_at WHERE penny_triage_status_clock.status!=excluded.status; END;
CREATE TABLE penny_evidence_snoozes (
 evidence_id TEXT PRIMARY KEY REFERENCES evidence_items(id) ON DELETE CASCADE, until_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE TABLE penny_triage_reminders (
 id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN ('inbox','comment','response','stale')),
 request_id TEXT REFERENCES requests(id) ON DELETE CASCADE,evidence_id TEXT REFERENCES evidence_items(id) ON DELETE CASCADE,comment_id TEXT REFERENCES request_comments(id) ON DELETE CASCADE,
 owner_operator_id TEXT NOT NULL REFERENCES operators(id),age_origin TEXT NOT NULL,age_step INTEGER NOT NULL CHECK(age_step>0),created_at TEXT NOT NULL
);
CREATE UNIQUE INDEX penny_triage_reminder_once ON penny_triage_reminders(kind,COALESCE(request_id,''),COALESCE(evidence_id,''),COALESCE(comment_id,''),owner_operator_id,age_origin,age_step);
CREATE INDEX penny_triage_reminder_owner ON penny_triage_reminders(owner_operator_id,created_at);
CREATE TRIGGER data_guard_penny_triage_settings_insert BEFORE INSERT ON penny_triage_settings WHEN NOT EXISTS(SELECT 1 FROM data_state s WHERE s.singleton=1 AND (s.phase='idle' OR (s.phase='applying' AND EXISTS(SELECT 1 FROM data_apply_claims c WHERE c.operation_id=s.lock_id)))) BEGIN SELECT RAISE(ABORT,'data_maintenance'); END;
CREATE TRIGGER feedback_native_penny_triage_settings_insert AFTER INSERT ON penny_triage_settings BEGIN UPDATE feedback_import_native_revision SET revision=revision+1 WHERE singleton=1; END;
CREATE TRIGGER data_guard_penny_triage_settings_update BEFORE UPDATE ON penny_triage_settings WHEN NOT EXISTS(SELECT 1 FROM data_state s WHERE s.singleton=1 AND (s.phase='idle' OR (s.phase='applying' AND EXISTS(SELECT 1 FROM data_apply_claims c WHERE c.operation_id=s.lock_id)))) BEGIN SELECT RAISE(ABORT,'data_maintenance'); END;
