CREATE TRIGGER triage_reminder_audit AFTER INSERT ON penny_triage_reminders WHEN (SELECT phase FROM data_state WHERE singleton=1)='idle' BEGIN
 INSERT INTO audit_entries(id,actor_type,action,entity_type,entity_id,occurred_at,details_json,created_at,updated_at) VALUES(lower(hex(randomblob(16))),'system','triage.reminded','triage_reminder',NEW.id,NEW.created_at,json_object('kind',NEW.kind,'step',NEW.age_step),NEW.created_at,NEW.created_at);
END;
